package nativeruntime

func appendProgressV12(fields []wireField,p *StreamProgress)[]wireField{
	if p.StreamSequence!=nil{fields=append(fields,optionalU64(FieldStreamSequence,*p.StreamSequence))}
	values:=[]struct{id FieldID;value *uint64}{{FieldElapsedUS,p.ElapsedUS},{FieldPromptTokens,p.PromptTokens},{FieldCachedTokens,p.CachedTokens},{FieldRemainingTokens,p.RemainingTokens},{FieldPrefillProcessedTokens,p.PrefillProcessedTokens},{FieldPrefillTotalTokens,p.PrefillTotalTokens},{FieldCompletionTokens,p.CompletionTokens},{FieldTTFTUS,p.TTFTUS},{FieldActivationUS,p.ActivationUS},{FieldProgressFlags,p.ProgressFlags},{FieldPromptEstimatedTokens,p.PromptEstimatedTokens},{FieldPrefillObservedTokens,p.PrefillObservedTokens},{FieldPrefillObservedElapsedUS,p.PrefillObservedElapsedUS},{FieldIngestionProcessed,p.IngestionProcessed},{FieldIngestionTotal,p.IngestionTotal},{FieldIngestionProcessedBytes,p.IngestionProcessedBytes},{FieldIngestionTotalBytes,p.IngestionTotalBytes},{FieldIngestionStartLine,p.IngestionStartLine},{FieldIngestionEndLine,p.IngestionEndLine}}
	for _,entry:=range values{if entry.value!=nil{fields=append(fields,optionalU64(entry.id,*entry.value))}}
	strings:=[]struct{id FieldID;value *string}{{FieldCacheHitType,p.CacheHitType},{FieldReadingSource,p.ReadingSource},{FieldReadingExcerpt,p.ReadingExcerpt},{FieldIngestionSourceID,p.IngestionSourceID},{FieldIngestionSourceName,p.IngestionSourceName},{FieldIngestionNote,p.IngestionNote}}
	for _,entry:=range strings{fields=appendOptionalString(fields,entry.id,entry.value)}
	return fields
}

