func progressSchemaV12(r,o func(WireType)fieldRule)map[FieldID]fieldRule{return map[FieldID]fieldRule{FieldProgressPhase:r(WireU32),FieldProgressFraction:r(WireF64),FieldProgressMessage:o(WireUTF8),FieldProgressCurrent:o(WireU64),FieldProgressTotal:o(WireU64),FieldStreamSequence:o(WireU64),FieldElapsedUS:o(WireU64),FieldPromptTokens:o(WireU64),FieldCachedTokens:o(WireU64),FieldRemainingTokens:o(WireU64),FieldPrefillProcessedTokens:o(WireU64),FieldPrefillTotalTokens:o(WireU64),FieldCompletionTokens:o(WireU64),FieldCacheHitType:o(WireUTF8),FieldTTFTUS:o(WireU64),FieldActivationUS:o(WireU64),FieldProgressFlags:o(WireU64),FieldPromptEstimatedTokens:o(WireU64),FieldReadingSource:o(WireUTF8),FieldReadingExcerpt:o(WireUTF8),FieldPrefillObservedTokens:o(WireU64),FieldPrefillObservedElapsedUS:o(WireU64),FieldIngestionSourceID:o(WireUTF8),FieldIngestionSourceName:o(WireUTF8),FieldIngestionProcessed:o(WireU64),FieldIngestionTotal:o(WireU64),FieldIngestionProcessedBytes:o(WireU64),FieldIngestionTotalBytes:o(WireU64),FieldIngestionStartLine:o(WireU64),FieldIngestionEndLine:o(WireU64),FieldIngestionNote:o(WireUTF8)}}
